from __future__ import annotations

import asyncio
from dataclasses import dataclass, field
from typing import Any, Awaitable, Callable, Mapping


class GraphError(ValueError):
    pass


class CycleError(GraphError):
    def __init__(self, cycle: list[str]):
        self.cycle = cycle
        super().__init__("dependency cycle: " + " -> ".join(cycle))


@dataclass
class PriorResult:
    state: str
    output: Any = None


@dataclass
class RunResult:
    succeeded: list[str] = field(default_factory=list)
    failed: dict[str, BaseException] = field(default_factory=dict)
    skipped: list[str] = field(default_factory=list)
    outputs: dict[str, Any] = field(default_factory=dict)


Worker = Callable[[str, Any], Awaitable[Any]]


async def run_graph(
    tasks: Mapping[str, Any],
    deps: Mapping[str, set[str]],
    worker: Worker,
    *,
    concurrency: int = 4,
    prior: Mapping[str, PriorResult] | None = None,
) -> RunResult:
    """Execute *tasks* after their dependencies have succeeded."""
    if concurrency < 1:
        raise ValueError("concurrency must be positive")

    # Take a snapshot: callers mutating either mapping while workers are
    # running must not change the graph halfway through a run.
    task_values = dict(tasks)
    dependency_sets = {name: set(deps.get(name, set())) for name in task_values}

    unknown_owners = set(deps) - set(task_values)
    if unknown_owners:
        names = ", ".join(sorted(unknown_owners))
        raise GraphError(f"dependencies specified for unknown task(s): {names}")

    for name, requirements in dependency_sets.items():
        if name in requirements:
            raise GraphError(f"task {name!r} cannot depend on itself")
        unknown = requirements - set(task_values)
        if unknown:
            names = ", ".join(sorted(unknown))
            raise GraphError(f"task {name!r} has unknown dependency/dependencies: {names}")

    # Detect cycles before starting any worker.  The active DFS stack lets us
    # report the actual closed path rather than merely the nodes in a cycle.
    visited: set[str] = set()
    active: dict[str, int] = {}
    path: list[str] = []

    def visit(name: str) -> None:
        if name in active:
            start = active[name]
            raise CycleError(path[start:] + [name])
        if name in visited:
            return
        active[name] = len(path)
        path.append(name)
        for requirement in sorted(dependency_sets[name]):
            visit(requirement)
        path.pop()
        del active[name]
        visited.add(name)

    for name in sorted(task_values):
        visit(name)

    result = RunResult()
    state: dict[str, str] = {}
    prior = prior or {}

    for name in sorted(task_values):
        old = prior.get(name)
        if old is not None and old.state == "succeeded" and old.output is not None:
            state[name] = "succeeded"
            result.succeeded.append(name)
            result.outputs[name] = old.output

    pending = set(task_values) - set(state)
    running: dict[asyncio.Task[tuple[bool, Any]], str] = {}

    async def invoke(name: str) -> tuple[bool, Any]:
        try:
            return True, await worker(name, task_values[name])
        except BaseException as error:
            return False, error

    while pending or running:
        # A skipped dependency is just as terminal as a failed one. Repeating
        # this pass handles arbitrarily long chains without running workers.
        changed = True
        while changed:
            changed = False
            for name in sorted(pending):
                if any(state.get(dep) in {"failed", "skipped"} for dep in dependency_sets[name]):
                    pending.remove(name)
                    state[name] = "skipped"
                    result.skipped.append(name)
                    changed = True

        capacity = concurrency - len(running)
        ready = sorted(
            name
            for name in pending
            if all(state.get(dep) == "succeeded" for dep in dependency_sets[name])
        )
        for name in ready[:capacity]:
            pending.remove(name)
            task = asyncio.create_task(invoke(name))
            running[task] = name

        if not running:
            # Validation above makes this unreachable for a static graph, but
            # retaining the guard prevents an accidental infinite loop.
            result.skipped.extend(sorted(pending))
            break

        done, _ = await asyncio.wait(running, return_when=asyncio.FIRST_COMPLETED)
        for task in sorted(done, key=lambda item: running[item]):
            name = running.pop(task)
            succeeded, value = task.result()
            if succeeded:
                state[name] = "succeeded"
                result.succeeded.append(name)
                result.outputs[name] = value
            else:
                state[name] = "failed"
                result.failed[name] = value

    return result
